  /* istruzioni d'uso del bot AI */
  Object.assign(DICT.it, {"ai.help_btn": "Come si usa", "ai.help_title": "Come si usa l'assistente", "ai.help_ok": "Ho capito", "ai.help_html": "<li><b>Clic sul bot</b>: apre e chiude questa finestra.</li><li><b>Domande pronte</b>: scegli una delle domande proposte per avere un consiglio sui tuoi dati.</li><li><b>Spostalo</b>: tieni premuto il bot e trascinalo dove dà meno fastidio; quando lo lasci si aggancia al bordo più vicino.</li><li><b>Resta dove l'hai messo</b>: la posizione viene ricordata anche se ricarichi la pagina.</li><li><b>Rimettilo a posto</b>: doppio clic sul bot e torna in basso a destra.</li>"});
  Object.assign(DICT.en, {"ai.help_btn": "How to use it", "ai.help_title": "How to use the assistant", "ai.help_ok": "Got it", "ai.help_html": "<li><b>Click the bot</b>: opens and closes this window.</li><li><b>Ready-made questions</b>: pick one of the suggested questions to get advice on your data.</li><li><b>Move it</b>: press and hold the bot, then drag it out of the way; when you let go it snaps to the nearest edge.</li><li><b>It stays put</b>: the position is remembered even after reloading the page.</li><li><b>Put it back</b>: double-click the bot and it returns to the bottom right.</li>"});
  Object.assign(DICT.es, {"ai.help_btn": "Cómo se usa", "ai.help_title": "Cómo usar el asistente", "ai.help_ok": "Entendido", "ai.help_html": "<li><b>Clic en el bot</b>: abre y cierra esta ventana.</li><li><b>Preguntas listas</b>: elige una de las preguntas propuestas para recibir un consejo sobre tus datos.</li><li><b>Muévelo</b>: mantén pulsado el bot y arrástralo donde moleste menos; al soltarlo se pega al borde más cercano.</li><li><b>Se queda donde lo dejas</b>: la posición se recuerda aunque recargues la página.</li><li><b>Devuélvelo a su sitio</b>: doble clic en el bot y vuelve abajo a la derecha.</li>"});
  Object.assign(DICT.fr, {"ai.help_btn": "Mode d'emploi", "ai.help_title": "Comment utiliser l'assistant", "ai.help_ok": "Compris", "ai.help_html": "<li><b>Clic sur le bot</b> : ouvre et ferme cette fenêtre.</li><li><b>Questions prêtes</b> : choisissez l'une des questions proposées pour obtenir un conseil sur vos données.</li><li><b>Déplacez-le</b> : maintenez le bot appuyé et faites-le glisser là où il gêne le moins ; relâché, il se colle au bord le plus proche.</li><li><b>Il reste en place</b> : la position est mémorisée même après avoir rechargé la page.</li><li><b>Remettez-le en place</b> : double-clic sur le bot et il revient en bas à droite.</li>"});
  Object.assign(DICT.de, {"ai.help_btn": "So funktioniert's", "ai.help_title": "So nutzt du den Assistenten", "ai.help_ok": "Verstanden", "ai.help_html": "<li><b>Klick auf den Bot</b>: öffnet und schließt dieses Fenster.</li><li><b>Fertige Fragen</b>: wähle eine der vorgeschlagenen Fragen, um einen Rat zu deinen Daten zu bekommen.</li><li><b>Verschieben</b>: Bot gedrückt halten und dorthin ziehen, wo er weniger stört; beim Loslassen rastet er am nächsten Rand ein.</li><li><b>Er bleibt, wo du ihn hinlegst</b>: die Position bleibt auch nach dem Neuladen gespeichert.</li><li><b>Zurücksetzen</b>: Doppelklick auf den Bot und er kehrt nach unten rechts zurück.</li>"});
  Object.assign(DICT.pt, {"ai.help_btn": "Como se usa", "ai.help_title": "Como usar o assistente", "ai.help_ok": "Percebi", "ai.help_html": "<li><b>Clique no bot</b>: abre e fecha esta janela.</li><li><b>Perguntas prontas</b>: escolhe uma das perguntas propostas para receber um conselho sobre os teus dados.</li><li><b>Move-o</b>: mantém o bot premido e arrasta-o para onde incomoda menos; ao soltar, encaixa no lado mais próximo.</li><li><b>Fica onde o deixas</b>: a posição é lembrada mesmo depois de recarregar a página.</li><li><b>Repõe-no no lugar</b>: duplo clique no bot e volta ao canto inferior direito.</li>"});
  Object.assign(DICT.nl, {"ai.help_btn": "Zo werkt het", "ai.help_title": "Zo gebruik je de assistent", "ai.help_ok": "Begrepen", "ai.help_html": "<li><b>Klik op de bot</b>: opent en sluit dit venster.</li><li><b>Kant-en-klare vragen</b>: kies een van de voorgestelde vragen voor advies over je gegevens.</li><li><b>Verplaatsen</b>: houd de bot ingedrukt en sleep hem waar hij minder stoort; bij loslaten klikt hij vast aan de dichtstbijzijnde rand.</li><li><b>Hij blijft staan</b>: de positie wordt onthouden, ook na het herladen van de pagina.</li><li><b>Terugzetten</b>: dubbelklik op de bot en hij gaat terug naar rechtsonder.</li>"});

